// ─── Against the real payslip ───────────────────────────────────────────────
//
// "Обрачун зараде и накнаде — Team Regular 2026-08", Radović Vladimir,
// generated by MPP on 24.09.2026. Every figure asserted here is printed on
// that sheet. It is the specification, and this is the check that the layout
// was read and not merely glanced at.

import { payslipFor } from './payslip'
import { runsFor, type RunInput } from './runs'
import { splitContractedNet, RATES_2026 } from './engine'
import { emptyTimesheet, type TimesheetRow } from './timesheets'
import type { EmployeeForMonth, EmployeeRow, ContractRow, DeductionRow } from './employees'

const MONTH = '2026-08'
const FUND = 168                      // August 2026: 21 working days
const RATE = 117.3586
const COEF = 0.004
const CONTRACTED = 234717.20          // 2,000 EUR at 117.3586

const employee = (over: Partial<EmployeeRow> = {}): EmployeeRow => ({
  id: 'e1', company_id: 'c1', code: 'E001', full_name: 'Radović Vladimir',
  organisational_unit: 'UPR - Uprava', hired_on: null,
  seniority_from: '2017-11-13', left_on: null, note: null, deleted_at: null, ...over,
})

const contract = (over: Partial<ContractRow> = {}): ContractRow => ({
  id: 'k1', employee_id: 'e1', valid_from: '2026-08-01', valid_to: null,
  currency: 'EUR', net_amount: 2000, service_years: null,
  note: null, ...over,
})

/** The one on the sheet: 140.64 EUR, 16,505.31 dinars at that month's rate. */
const familyInsurance: DeductionRow = {
  id: 'd1', employee_id: 'e1',
  label: 'Osigurani članovi porodice Jovana, Vuk i Lazar',
  goes_to: 'employer', payee: 'KALEMAR D.O.O.',
  amount: 140.64, currency: 'EUR', percent_of_net: null,
  valid_from: '2026-02-01', valid_to: '2027-01-31', is_active: true, note: null,
}

const person = (over: Partial<EmployeeForMonth> = {}): EmployeeForMonth => ({
  employee: employee(), contract: contract(),
  // Eight years of service — the sheet prints "коефицијент минулог рада 8,00  3,20".
  net: splitContractedNet(CONTRACTED, 8, COEF),
  deductions: [familyInsurance],
  allocation: null,
  serviceYears: 8, serviceYearsDerived: true, ...over,
})

const sheet = (over: Partial<TimesheetRow> = {}): TimesheetRow =>
  ({ ...emptyTimesheet('e1', MONTH), ...over })

const input = (over: Partial<RunInput> = {}): RunInput => ({
  people: [person()],
  timesheets: { e1: sheet({ regular_hours: FUND }) },
  rates: RATES_2026, monthHours: FUND, month: MONTH,
  currencyRates: { EUR: RATE },
  coefficients: { godisnji_odmor: 1 },
  ...over,
})

const slip = (over: Partial<RunInput> = {}) => {
  const r = runsFor(input(over))
  const line = r.runs.find(x => x.key === 'regular')!.salaries[0]
  return payslipFor(line, person(), RATES_2026, COEF, { EUR: RATE })
}

describe('општи подаци', () => {
  const p = slip()

  it('splits the contracted net the way the sheet does', () => {
    // 1 укупан нето износ 234.717,20
    // 2 минули рад 7.278,05
    // 3 основна нето зарада 227.439,15
    expect(p.contractedNet).toBeCloseTo(234717.20, 2)
    expect(p.seniorityNet).toBeCloseTo(7278.05, 1)
    expect(p.baseNet).toBeCloseTo(227439.15, 1)
  })

  it('prints the seniority as years and a percentage', () => {
    // 4 коефицијент минулог рада 8,00  3,20
    expect(p.serviceYears).toBe(8)
    expect(p.seniorityPercent).toBeCloseTo(3.20, 4)
  })

  it('shows the hours in the run and the hours in the month', () => {
    // 5 сати радника у обрачуну 168,00 · 6 сати у месецу 168,00
    expect(p.hours).toBe(168)
    expect(p.monthHours).toBe(168)
  })
})

describe('цена сати', () => {
  const p = slip()

  it('prices an hour of work, net and gross', () => {
    // 1 цена рада по часу 1.353,80  1.902,19
    expect(p.workPerHourNet).toBeCloseTo(1353.80, 1)
    expect(p.workPerHourGross).toBeCloseTo(1902.19, 1)
  })

  it('prices an hour of the allowance, net and gross', () => {
    // 2 цена накнаде по часу 1.397,13  1.963,99
    expect(p.allowancePerHourNet).toBeCloseTo(1397.13, 1)
    expect(p.allowancePerHourGross).toBeCloseTo(1963.99, 1)
  })
})

describe('делови зараде/накнаде', () => {
  const p = slip()
  const part = (label: string) => p.parts.find(x => x.label === label)!

  it('lists the four parts the sheet lists', () => {
    expect(p.parts.map(x => x.label))
      .toEqual(['Regular work', 'Meal allowance', 'Holiday allowance', 'Seniority'])
  })

  it('grosses each one the way the sheet does', () => {
    // 1 редован рад 168,00 | 227.439,15 | 319.567,83
    // 2 топли оброк 168,00 |     100,00 |     142,65
    // 3 регрес              |     100,00 |     142,65
    // 4 минули рад          |   7.278,05 |  10.382,38
    expect(part('Regular work').net).toBeCloseTo(227439.15, 1)
    expect(part('Regular work').gross).toBeCloseTo(319567.83, 0)
    expect(part('Meal allowance').net).toBeCloseTo(100, 2)
    expect(part('Meal allowance').gross).toBeCloseTo(142.65, 1)
    expect(part('Holiday allowance').gross).toBeCloseTo(142.65, 1)
    expect(part('Seniority').net).toBeCloseTo(7278.05, 1)
    expect(part('Seniority').gross).toBeCloseTo(10382.38, 1)
  })

  it('adds the parts to the gross EXACTLY', () => {
    // The whole reason regular work takes the remainder. A payslip whose
    // parts do not sum to its own total is worse than one showing no parts.
    const sum = p.parts.reduce((s, x) => s + x.gross, 0)
    expect(Math.round(sum * 100)).toBe(Math.round(p.gross * 100))
  })

  it('gives only the worked parts their hours', () => {
    expect(part('Regular work').hours).toBe(168)
    expect(part('Holiday allowance').hours).toBeNull()
    expect(part('Seniority').hours).toBeNull()
  })
})

describe('зарада, порез и доприноси', () => {
  const p = slip()
  const charge = (label: string) => p.employeeCharges.find(c => c.label.startsWith(label))!

  it('matches the five figures at the top of the block', () => {
    // 1 бруто 330.235,52 · 2 основица 330.235,52 · 3 неопорезив 34.221,00
    // 4 пореска основица 296.014,52 · 5 на терет запосленог 95.318,32
    expect(p.gross).toBeCloseTo(330235.52, 0)
    expect(p.contributionBase).toBeCloseTo(330235.52, 0)
    expect(p.taxFree).toBeCloseTo(34221.00, 2)
    expect(p.taxBase).toBeCloseTo(296014.52, 0)
    expect(p.employeeTotal).toBeCloseTo(95318.32, 0)
  })

  it('shows the base beside the gross even where they are the same', () => {
    // They are equal for everybody under the ceiling, and the field exists
    // for the one person who is over it.
    expect(p.contributionBase).toBe(p.gross)
  })

  it('names each charge with the rate the sheet prints', () => {
    expect(charge('Income tax').percent).toBe(10)
    expect(charge('Income tax').amount).toBeCloseTo(29601.45, 0)
    expect(charge('Pension').percent).toBe(14)
    expect(charge('Pension').amount).toBeCloseTo(46232.97, 0)
    expect(charge('Health').percent).toBe(5.15)
    expect(charge('Health').amount).toBeCloseTo(17007.13, 0)
    expect(charge('Unemployment').percent).toBe(0.75)
    expect(charge('Unemployment').amount).toBeCloseTo(2476.77, 0)
  })

  it('reaches the same net the sheet reaches', () => {
    // 6 нето износ 234.917,20 — the contracted total plus the 200 allowances
    expect(p.net).toBeCloseTo(234917.20, 0)
  })
})

describe('обуставе', () => {
  const p = slip()

  it('names the deduction and converts it at the month rate', () => {
    // 7 обуставе 16.505,31 — 140.64 EUR at 117.3586
    expect(p.deductions).toHaveLength(1)
    expect(p.deductions[0].label).toContain('Osigurani članovi porodice')
    expect(p.deductions[0].amount).toBeCloseTo(16505.31, 1)
    expect(p.deductionsTotal).toBeCloseTo(16505.31, 1)
  })

  it('reaches the net actually paid', () => {
    // 8 нето за исплату 218.411,89
    expect(p.netPaid).toBeCloseTo(218411.89, 0)
  })

  it('says whether each one leaves the company', () => {
    expect(p.deductions[0].goesTo).toBe('employer')
  })
})

describe('доприноси на терет послодавца', () => {
  const p = slip()

  it('matches the employer block line for line', () => {
    // ПИО 10,00 33.023,55 · здравствено 5,15 17.007,13 · незапосленост 0 · total 50.030,68
    const pension = p.employerCharges.find(c => c.label.startsWith('Pension'))!
    const health = p.employerCharges.find(c => c.label.startsWith('Health'))!
    expect(pension.percent).toBe(10)
    expect(pension.amount).toBeCloseTo(33023.55, 0)
    expect(health.amount).toBeCloseTo(17007.13, 0)
    expect(p.employerTotal).toBeCloseTo(50030.68, 0)
  })
})

describe('the cost of the payslip', () => {
  it('is the gross plus the employer’s contributions', () => {
    const p = slip()
    expect(p.totalCost).toBeCloseTo(p.gross + p.employerTotal, 1)
  })
})

describe('a part month', () => {
  it('prorates the seniority shown alongside everything else', () => {
    const p = (() => {
      const r = runsFor(input({ timesheets: { e1: sheet({ regular_hours: 84 }) } }))
      const line = r.runs.find(x => x.key === 'regular')!.salaries[0]
      return payslipFor(line, person(), RATES_2026, COEF, { EUR: RATE })
    })()
    const seniority = p.parts.find(x => x.label === 'Seniority')!
    expect(seniority.net).toBeCloseTo(7278.05 / 2, 0)
    expect(p.hours).toBe(84)
    expect(p.monthHours).toBe(168)
    // And the parts still add to the gross exactly.
    const sum = p.parts.reduce((s, x) => s + x.gross, 0)
    expect(Math.round(sum * 100)).toBe(Math.round(p.gross * 100))
  })
})
